def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    numerator = 0.0
    weight = 0.0
    for element, fraction in s.get('composition', {}).items():
        r = props.get(element, {}).get('covalent_radius_A')
        if fraction is not None and fraction > 0 and r is not None and math.isfinite(r) and r > 0:
            numerator += fraction * r ** 3
            weight += fraction
    if weight <= 0:
        return 0.0
    return float(4.0 * math.pi * numerator / (3.0 * weight * v))

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    electrons = 0.0
    weight = 0.0
    for element, fraction in s.get('composition', {}).items():
        z = props.get(element, {}).get('valence_electrons')
        if fraction is not None and fraction > 0 and z is not None and math.isfinite(z):
            electrons += fraction * z
            weight += fraction
    if weight <= 0:
        return 0.0
    return float(electrons / (weight * v))

def feature(s):
    sites = s.get('sites', [])
    n = len(sites)
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    total = sum(occ)
    if n == 0 or total <= 0:
        return 0.0
    neighbors = s.get('neighbors', [])
    nearest = [math.inf] * n
    for b in neighbors:
        i = b['i']
        j = b['j']
        d = b['distance_A']
        if occ[j] > 0 and d > 0 and d < nearest[i]:
            nearest[i] = d
    contacts = 0.0
    for b in neighbors:
        i = b['i']
        j = b['j']
        d = b['distance_A']
        if d > 0 and d <= 1.25 * nearest[i]:
            contacts += occ[i] * occ[j]
    return float(contacts / total)

def feature(s):
    sites = s.get('sites', [])
    n = len(sites)
    if n == 0:
        return 0.0
    props = s.get('element_properties', {})
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    en = [props.get(t['element'], {}).get('eneg') for t in sites]
    neighbors = s.get('neighbors', [])
    nearest = [math.inf] * n
    for b in neighbors:
        i = b['i']
        j = b['j']
        d = b['distance_A']
        if occ[j] > 0 and d > 0 and d < nearest[i]:
            nearest[i] = d
    env_sum = [0.0] * n
    env_weight = [0.0] * n
    for b in neighbors:
        i = b['i']
        j = b['j']
        d = b['distance_A']
        if d > 0 and d <= 1.25 * nearest[i] and en[j] is not None:
            if math.isfinite(en[j]):
                env_sum[i] += occ[j] * en[j]
                env_weight[i] += occ[j]
    groups = {}
    for i in range(n):
        if occ[i] > 0 and env_weight[i] > 0:
            value = env_sum[i] / env_weight[i]
            element = sites[i]['element']
            w, a, b = groups.get(element, (0.0, 0.0, 0.0))
            groups[element] = (w + occ[i], a + occ[i] * value, b + occ[i] * value * value)
    variance_sum = 0.0
    total = 0.0
    for w, a, b in groups.values():
        if w > 0:
            variance_sum += max(0.0, b - a * a / w)
            total += w
    return float(math.sqrt(variance_sum / total)) if total > 0 else 0.0
